  if(q.includes('water heater'))return {signs:['no hot water','temperature changes','unusual tank noises','water around the unit'],prep:['gas or electric fuel type','tank or tankless style','approximate unit age','where any leak appears'],scope:'The contractor may first distinguish between controls, heating components, venting, supply connections and tank condition before discussing repair or replacement.'};
