  if(q.includes('toilet'))return {signs:['a running toilet','weak flushing','recurring clogs','water near the base'],prep:['whether it overflows','whether it runs continuously','where leaking appears'],scope:'A toilet call may involve the fill and flush components, seal, supply connection, trapway or the drain serving the fixture.'};
  if(q.includes('sump'))return {signs:['a pump that will not start','unusual cycling','new operating noises','water rising faster than the pump removes it'],prep:['when the issue happens','whether the pit fills normally','whether backup power is present'],scope:'Inspection can include the pump, float, discharge path, check valve and power source before replacement is considered.'};
  if(q.includes('garbage'))return {signs:['a jammed disposal','humming without turning','a leak','slow drainage'],prep:['whether the unit has power','where a leak appears','whether the sink also drains slowly'],scope:'The cause can be electrical, mechanical, a connection leak or a drainage problem; keep hands out of the disposal while troubleshooting.'};
  if(q.includes('hydro'))return {signs:['recurring line blockages','heavy buildup','slow flow that returns after basic clearing'],prep:['what cleaning has already been tried','whether the line has been camera-inspected','how often the blockage returns'],scope:'High-pressure cleaning is normally considered after the line condition and the nature of the blockage are understood.'};
