  if(q.includes('pipe'))return {signs:['visible pipe leakage','corrosion','low pressure','repeated trouble at one section'],prep:['where the symptoms appear','what the pipe serves','whether the issue is isolated or widespread'],scope:'The first evaluation can help determine whether a fitting, short section, supply run or broader piping condition is involved.'};
