function serviceBlurb(service){const q=String(service||'').toLowerCase(),p=serviceProfile(service);if(q.includes('drain'))return 'Help with slow drains, recurring clogs and backed-up fixtures.';if(q.includes('leak'))return 'Help diagnosing visible or suspected plumbing leaks.';if(q.includes('water heater'))return 'Service help for tank and tankless water-heater problems.';if(q.includes('sewer'))return 'Help with recurring backups, odors and sewer-line concerns.';if(q.includes('pipe'))return 'Help with leaking, damaged or replacement piping.';if(q.includes('emergency'))return 'Phone-first help for urgent plumbing problems when coverage is available.';return `Help with ${String(service||'service').toLowerCase()} concerns such as ${p.signs.slice(0,2).join(' and ')}.`;}
function serviceText(service,city,seed){const lower=String(service||'').toLowerCase();const intros=[`${service} needs in ${city.n} can range from routine service to problems that require prompt professional evaluation. Call to discuss the situation and current local contractor availability.`,`If you are looking for ${lower} in ${city.n}, start by identifying what changed, limiting avoidable damage when it is safe to do so and speaking with a contractor who handles this type of work.`,`${city.n} property owners looking for ${lower} can start with the condition they can observe, when it began and which part of the property or system appears to be affected.`,`Service needs involving ${lower} can develop gradually or appear without much warning. In ${city.n}, clear details about the problem can help a local contractor plan the first diagnostic step.`];const checks=[`Describe when the problem started, where it appears and what has changed. Clear observations can help the contractor narrow the likely cause.`,`Before work begins, ask what will be inspected first, what areas may need access and what conditions could change the scope of the service.`,`If there is an immediate safety or property-damage concern, follow appropriate emergency guidance and avoid using affected equipment or areas until a qualified professional can evaluate the problem.`,`Compare the proposed work with the actual symptoms you are seeing. A useful service conversation should explain the diagnostic step before jumping to major work.`];return {intro:pick(intros,seed,1),check:pick(checks,seed,2)};}
function serviceInsight(service,city,seed){
  const q=String(service||'').toLowerCase();
  const sets=q.includes('drain')?[
    'Slow drains, recurring clogs, gurgling sounds and backups are common reasons people request drain cleaning.',
    'Mention whether one fixture or several drains are affected, whether the problem returns after clearing, and when you first noticed it.'
  ]:q.includes('leak')?[
    'Visible dripping, damp cabinets or walls, unexplained moisture and sudden changes in water use can all point to a leak that needs diagnosis.',
    'Tell the contractor where moisture appears, whether it is constant or intermittent, and which fixtures or supply lines are nearby.'
  ]:q.includes('water heater')?[
    'No hot water, inconsistent temperatures, unusual noises and visible leaking around the unit are common water-heater service concerns.',
    'Have the fuel type, approximate unit age and the symptoms you are seeing ready when you call if that information is available.'
  ]:q.includes('sewer')?[
    'Multiple slow drains, repeated backups, sewer odors and gurgling across several fixtures can indicate a sewer-line problem rather than a single clogged drain.',
    'Describe how many fixtures are affected and whether the symptoms happen at the same time so the contractor can plan the first diagnostic step.'
  ]:q.includes('pipe')?[
    'Pipe problems may show up as visible leaks, corrosion, low pressure, water stains or repeated issues at the same section of plumbing.',
    'Point out where the symptoms appear and whether the affected line serves one fixture, one room or a larger part of the property.'
  ]:q.includes('toilet')?[
    'Running toilets, recurring clogs, weak flushing, leaks at the base and fill problems are common reasons for toilet repair.',
    'Mention whether the toilet is overflowing, continuously running, leaking or failing to flush normally.'
  ]:q.includes('sump')?[
    'A sump pump that will not start, cycles unusually, makes new noises or cannot keep up with incoming water may need inspection or replacement.',
    'Describe when the issue happens, whether the pit is filling normally and whether a backup power system is present.'
  ]:q.includes('garbage')?[
    'A disposal that jams, hums, leaks, drains slowly or will not turn on may need repair or replacement depending on the cause.',
    'Explain whether the problem is electrical, a jam, a leak or a drainage issue and avoid putting your hand inside the disposal.'
  ]:q.includes('hydro')?[
    'Hydro jetting is commonly considered for stubborn buildup or recurring line blockages after the condition of the drain or sewer line has been assessed.',
    'Ask what inspection is recommended before high-pressure cleaning and whether the line condition makes jetting appropriate.'
  ]:q.includes('filtration')?[
    'Water filtration needs vary with the water-quality concern, desired flow rate, fixture coverage and the type of system being considered.',
    'Describe what you want to improve and whether you are considering point-of-use or whole-home filtration.'
  ]:q.includes('backflow')?[
    'Backflow prevention work may involve inspection, testing, repair or installation depending on the device and local requirements.',
    'Confirm what type of device is present and whether your municipality or property manager has specific testing or documentation requirements.'
  ]:q.includes('fixture')||q.includes('bathroom')||q.includes('kitchen')?[
    'Dripping faucets, loose connections, poor flow, damaged valves and fixture replacements are common reasons for kitchen or bathroom plumbing service.',
    'Identify the fixture involved, what it is doing now and whether any shutoff or supply connection is also leaking.'
  ]:q.includes('commercial')?[
    'Commercial plumbing calls can involve higher-use fixtures, shared supply or drainage systems, equipment connections and operational disruption.',
    'When you call, explain the affected area, business-use impact and any access or scheduling constraints that matter for the property.'
  ]:q.includes('emergency')?[
    'Active leaks, overflowing fixtures, sudden loss of water service and wastewater backups are examples of problems people often treat as urgent.',
    'Describe the immediate condition clearly and follow safe property-protection steps while you wait for professional guidance.'
  ]:[
    `${service} can involve different symptoms, fixtures and repair options depending on the condition of the plumbing system.`,
    'Describe what you can observe, when it started and which fixtures are affected so the contractor can plan an appropriate first look.'
  ];
  return {signs:sets[0],prep:sets[1],variant:pick(['What you may notice','Common reasons to call','Before scheduling service','What to mention when you call'],seed,7)};
}
function localContext(M,city,service){
  const z=(city.z||[]).slice(0,5),near=(city.nb||[]).slice(0,4).map(k=>M.cities[k]).filter(Boolean).map(c=>c.n);
  const pieces=[];
  if(city.co)pieces.push(`${city.n} is in ${city.co}`);
  if(z.length)pieces.push(`commonly associated ZIP codes in the covered area include ${z.join(', ')}`);
  if(near.length)pieces.push(`nearby covered communities include ${near.join(', ')}`);
  const first=pieces.length?`${pieces.join('; ')}.`:`Service availability can vary by address within and around ${city.n}.`;
  return `${first} For ${String(service||'').toLowerCase()}, confirm availability for your address and the proposed scope when you call.`;
}
